3	/**
4	 * A class representing shared characteristics of consumers.
5	 *
6	 * @version 18.02.22 (DD:MM:YY)
7	 */
8	public abstract class Consumer extends Actor
9	{
10	    // Properties shared between all consumers:
11	    private static final int STARTING_SUSTENANCE_LEVEL = 30;
12	    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
13	
14	    // Properties unique to this consumer:
15	    private int breedingAge;
16	    private int sustenanceLevel;
17	    private int maxSustenanceLevel;
18	    private List<Class<?>> prey;
19	    private Disease disease;
20	    private boolean canEatCarcass;
21	
22	    /**
23	     * Create a new consumer at a location in the field.
24	     *
25	     * @param field               The field currently occupied.
26	     * @param location            The location within the field.
27	     * @param consumptionWorth    The worth of the consumer if consumed.
28	     * @param breedingProbability The likelihood of the consumer breeding.
29	     * @param maxBirthsAtOnce     The max number of births for the consumer.
30	     * @param maxAge              The age to which this consumer can live.
31	     * @param breedingAge         The age at which this consumer can start to breed.
32	     */
33	    public Consumer(Field field, Location location, List<Class<?>> prey, int consumptionWorth,
34	                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,
35	                    int maxSustenanceLevel, boolean canEatCarcass)
36	    {
37	        super(field, location, consumptionWorth, breedingProbability, maxBirthsAtOnce,
38	              maxSustenanceLevel, maxAge);
39	        this.canEatCarcass = canEatCarcass;
40	        this.prey = prey;
41	        this.breedingAge = breedingAge;
42	        sustenanceLevel = STARTING_SUSTENANCE_LEVEL;
43	    }
44	
45	    /**
46	     * Create a new offspring of this consumer type at the given location.
47	     * Subclasses return an instance of their own concrete type.
48	     *
49	     * @param field    The field to place the offspring in.
50	     * @param location The location to place the offspring at.
51	     * @return A new offspring Consumer.
52	     */
53	    protected abstract Consumer createOffspring(Field field, Location location);
54	
55	    /**
56	     * Make this consumer act - that is: make it do
57	     * whatever it wants/needs to do.
58	     *
59	     * @param newConsumers A list to receive newly born consumers.
60	     */
61	    public void act(List<Actor> newConsumers)
62	    {
63	        incrementAge();
64	        incrementHunger();
65	        if (getIsAlive())
66	        {
67	            giveBirth(newConsumers);
68	            boolean wasPossibleToMove = huntForFood(newConsumers);
69	            if (hasDisease())
70	            {
71	                diseaseEffect();
72	            }
73	            if (!wasPossibleToMove)
74	            {
75	                setDead();
76	            }
77	        }
78	    }
79	
80	    /** @return True if this consumer is currently diseased. */
81	    private boolean hasDisease()
82	    {
83	        return disease != null;
84	    }
85	
86	    /** @return A new Disease instance. */
87	    private Disease giveDisease()
88	    {
89	        return new Disease();
90	    }
91	
92	    /** Advance the disease by one step: progress timer, spread, then check lethality. */
93	    private void diseaseEffect()
94	    {
95	        disease.decrementStepsBeforeDeath();
96	        spreadDisease();
97	        checkForFatalDisease();
98	        incrementHunger();
99	    }
100	
101	    /** Resolve the disease if it has run its course. */
102	    private void checkForFatalDisease()
103	    {
104	        if (disease.diseaseFinished())
105	        {
106	            if (disease.isFatal())
107	            {
108	                setDead();
109	            }
110	            disease = null;
111	        }
112	    }
113	
114	    /** Spread the disease to all adjacent consumers of the same species. */
115	    private void spreadDisease()
116	    {
117	        Field field = getField();
118	        for (Location loc : field.adjacentLocations(getLocation()))
119	        {
120	            Object animal = field.getObjectAt(loc);
121	            if (animal != null && animal.getClass() == this.getClass())
122	            {
123	                ((Consumer) animal).disease = giveDisease();
124	            }
125	        }
126	    }
127	
128	    /** Hunt for food by moving toward it. */
129	    private boolean huntForFood(List<Actor> newActors)
130	    {
131	        Location newLocation = findFood(newActors);
132	
133	        if (newLocation == null)
134	        {
135	            newLocation = getField().freeAdjacentLocation(getLocation());
136	        }
137	
138	        if (newLocation != null) setLocation(newLocation);
139	
140	        return newLocation != null;
141	    }
142	
143	    /**
144	     * Set the starting age of the consumer, dependent on whether a random
145	     * age has been selected.
146	     *
147	     * @param randomAge If true, the age is random, otherwise it's 0.
148	     */
149	    protected void setStartingAge(boolean randomAge)
150	    {
151	        if (randomAge) setCurrentAge(rand.nextInt(getMaxAge()));
152	        else           setCurrentAge(0);
153	    }
154	
155	    /**
156	     * Check whether or not this consumer is to give birth at this step.
157	     * New births will be made into free adjacent locations.
158	     *
159	     * @param newConsumers A list to return newly born consumers.
160	     */
161	    private void giveBirth(List<Actor> newConsumers)
162	    {
163	        if (!checkForValidMate()) return;
164	
165	        Field field = getField();
166	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
167	
168	        int births = breed();
169	        for (int b = 0; b < births && free.size() > 0; b++)
170	        {
171	            Location location = free.remove(0);
172	            newConsumers.add(createOffspring(field, location));
173	        }
174	    }
175	
176	    /**
177	     * @return True if there is a valid mate in an adjacent location for the consumer.
178	     */
179	    private boolean checkForValidMate()
180	    {
181	        Field field = getField();
182	
183	        for (Location location : field.adjacentLocations(getLocation()))
184	        {
185	            Object object = field.getObjectAt(location);
186	
187	            if (object instanceof Consumer other
188	                && other.getClass() == this.getClass()
189	                && other.canBreed()
190	                && other.getGender() != getGender())
191	            {
192	                return true;
193	            }
194	        }
195	
196	        return false;
197	    }
198	
199	    /**
200	     * Generate a number representing the number of births,
201	     * if it can breed.
202	     *
203	     * @return The number of births (may be zero).
204	     */
205	    private int breed()
206	    {
207	        boolean willBreed = rand.nextDouble() <= getBreedingProbability();
208	        return (canBreed() && willBreed) ? rand.nextInt(getMaxBirthsAtOnce()) + 1 : 0;
209	    }
210	
211	    /**
212	     * A consumer can breed if it has reached the breeding age.
213	     *
214	     * @return True if the consumer can breed, false otherwise.
215	     */
216	    private boolean canBreed() { return getCurrentAge() >= breedingAge; }
217	
218	    /**
219	     * Make this consumer more hungry. This could result in the consumer's death.
220	     */
221	    private void incrementHunger()
222	    {
223	        sustenanceLevel--;
224	        if (sustenanceLevel <= 0) setDead();
225	    }
226	
227	    /**
228	     * Look for prey adjacent to the current location.
229	     * Only the first live prey is eaten.
230	     *
231	     * @return Where food was found, or null if it wasn't.
232	     */
233	    private Location findFood(List<Actor> newActors)
234	    {
235	        Field field = getField();
236	
237	        for (Location where : field.adjacentLocations(getLocation()))
238	        {
239	            Object object = field.getObjectAt(where);
240	
241	            for (Class<?> preyClass : prey)
242	            {
243	                if (preyClass.isInstance(object))
244	                {
245	                    Actor actor = (Actor) object;
246	                    if (actor.getIsAlive())
247	                    {
248	                        boolean canHit = !TimeSystem.isNightTime()
249	                                      || rand.nextDouble() <= 1.0 - NIGHT_PREY_MISS_PROBABILITY;
250	                        if (canHit)
251	                            return eat(actor, newActors);
252	                    }
253	                }
254	            }
255	
256	            if (object instanceof Carcass carcass && canEatCarcass)
257	            {
258	                if (carcass.isDiseased())
259	                {
260	                    disease = giveDisease();
261	                }
262	                sustenanceLevel += carcass.getConsumptionWorth();
263	                carcass.setDead();
264	                return where;
265	            }
266	        }
267	
268	        return null;
269	    }
270	
271	    @Override
272	    protected boolean becomeCarcass()
273	    {
274	        return true;
275	    }
276	
277	    /**
278	     * Makes the animal eat the food and generate a carcass if necessary.
279	     * @param actor The actor who is to be eaten.
280	     */
281	    private Location eat(Actor actor, List<Actor> newActors)
282	    {
283	        Location location = actor.getLocation();
284	        int actorConsumptionWorth = actor.getConsumptionWorth();
285	        if (actor.becomeCarcass())
286	        {
287	            actor.setDead();
288	            if ((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
289	            {
290	                int foodLeft = (sustenanceLevel + getConsumptionWorth()) - maxSustenanceLevel;
291	                sustenanceLevel = maxSustenanceLevel;
292	                newActors.add(new Carcass(getField(), location, foodLeft));
293	                return getLocation();
294	            }
295	        }
296	        if (sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
297	        {
298	            sustenanceLevel += actorConsumptionWorth;
299	            return location;
300	        }
301	        return null;
302	    }
303	}
